e":"e67cf9f5ca856ee6505b2951f3527c70b1688dd29c4f06f5fbbdcb95a32eb7f0","hash_evaluado":"43af1f4641","hash_paquete_10":"e67cf9f5ca"},{"codigo":"S22A-C02","legacy_id":13118,"relacionadas":["S7-C07","S21-C07"],"residual":"No se acredita escritura real del último uso por usuario y dispositivo; binding runtime pendiente.","hechos":["s22a02_login_b2b","s22a02_nuevo_desconocido","s22a02_reconocido","s22a02_renovacion_ajena","s22a02_riesgo_revocacion_omitida","s22a02_otp_correo_completo","s22a02_sesion_operativa","dias_sin_uso_dispositivo"],"paquete":{"tipo":"NUEVA","codigo":"S22A-C02","clave":"s22a_legacy_13118","familia":"MFA_OTP_SSO","naturaleza":"CONDUCTA","clase":"TRANSVERSAL","alcance":"B2B","modo":"HEREDA","dueno":"TECNICO","titulo":"Inactividad y reconocimiento de dispositivo B2B","descripcion":"BLOQUEAR reconocer como confiable dispositivo nuevo, desconocido o cuya inactividad alcance AUTH/MFA_DEVICE_IDLE_DAYS de public.lf_global_config; exigir OTP correo antes de sesión operativa. El último uso autenticado se registra por usuario y dispositivo; BLOQUEAR renovar confianza por actividad ajena y omitir revocación ante señales de seguridad. Complementa S7-C07 y S21-C07, sin sustituir validación de token ni ciclo de revocación. Binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/13118","solicitante":"Cristhian / Claude S22-A 2026-11-24"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22a02_login_b2b"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22a02_renovacion_ajena"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22a02_riesgo_revocacion_omitida"},"der":{"lit":true}}},"der":{"op":"y","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22a02_nuevo_desconocido"},"der":{"lit":true}},"der":{"op":">=","izq":{"hecho":"dias_sin_uso_dispositivo"},"der":{"param":"AUTH.MFA_DEVICE_IDLE_DAYS"}}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22a02_reconocido"},"der":{"lit":true}},"der":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22a02_sesion_operativa"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22a02_otp_correo_completo"},"der":{"lit":false}}}}}}},"pruebas":[{"casuistica":"BAJO_EL_LIMITE","entrada":{"s22a02_login_b2b":true,"s22a02_nuevo_desconocido":false,"s22a02_reconocido":true,"s22a02_renovacion_ajena":false,"s22a02_riesgo_revocacion_omitida":false,"s22a02_otp_correo_completo":false,"s22a02_sesion_operativa":true,"dias_sin_uso_dispositivo":{"param":"AUTH.MFA_DEVICE_IDLE_DAYS","mas":-1}},"esperado":false},{"casuistica":"EN_EL_LIMITE","entrada":{"s22a02_login_b2b":true,"s22a02_nuevo_desconocido":false,"s22a02_reconocido":true,"s22a02_renovacion_ajena":false,"s22a02_riesgo_revocacion_omitida":false,"s22a02_otp_correo_completo":false,"s22a02_sesion_operativa":true,"dias_sin_uso_dispositivo":{"param":"AUTH.MFA_DEVICE_IDLE_DAYS","mas":0}},"esperado":true},{"casuistica":"SOBRE_EL_LIMITE","entrada":{"s22a02_login_b2b":true,"s22a02_nuevo_desconocido":false,"s22a02_reconocido":true,"s22a02_renovacion_ajena":false,"s22a02_riesgo_revocacion_omitida":false,"s22a02_otp_correo_completo":false,"s22a02_sesion_operativa":true,"dias_sin_uso_dispositivo":{"param":"AUTH.MFA_DEVICE_IDLE_DAYS","mas":1}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22a02_login_b2b":true,"s22a02_nuevo_desconocido":true,"s22a02_reconocido":true,"s22a02_renovacion_ajena":false,"s22a02_riesgo_revocacion_omitida":false,"s22a02_otp_correo_completo":false,"s22a02_sesion_operativa":true,"dias_sin_uso_dispositivo":{"param":"AUTH.MFA_DEVICE_IDLE_DAYS","mas":-1}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22a02_login_b2b":true,"s22a02_nuevo_desconocido":false,"s22a02_reconocido":true,"s22a02_renovacion_ajena":true,"s22a02_riesgo_revocacion_omitida":false,"s22a02_otp_correo_completo":false,"s22a02_sesion_operativa":true,"dias_sin_uso_dispositivo":{"param":"AUTH.MFA_DEVICE_IDLE_DAYS","mas":-1}},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22a02_login_b2b":true,"s22a02_nuevo_desconocido":false,"s22a02_reconocido":true,"s22a02_renovacion_ajena":false,"s22a02_riesgo_revocacion_omitida":true,"s22a02_otp_correo_completo":false,"s22a02_sesion_operativa":true,"dias_sin_uso_dispositivo":{"param":"AUTH.MFA_DEVICE_IDLE_DAYS","mas":-1}},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22a02_login_b2b":true,"s22a02_nuevo_desconocido":false,"s22a02_reconocido":false,"s22a02_renovacion_ajena":false,"s22a02_riesgo_revocacion_omitida":false,"s22a02_otp_correo_completo":true,"s22a02_sesion_operativa":true,"dias_sin_uso_dispositivo":{"param":"AUTH.MFA_DEVICE_IDLE_DAYS","mas":0}},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22a02_login_b2b":false,"s22a02_nuevo_desconocido":false,"s22a02_reconocido":true,"s22a02_renovacion_ajena":false,"s22a02_riesgo_revocacion_omitida":false,"s22a02_otp_correo_completo":false,"s22a02_sesion_operativa":true,"dias_sin_uso_dispositivo":{"param":"AUTH.MFA_DEVICE_IDLE_DAYS","mas":0}},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22a02_login_b2b":true,"s22a02_nuevo_desconocido":false,"s22a02_reconocido":false,"s22a02_renovacion_ajena":false,"s22a02_riesgo_revocacion_omitida":false,"s22a02_otp_correo_completo":false,"s22a02_sesion_operativa":true,"dias_sin_uso_dispositivo":{"param":"AUTH.MFA_DEVICE_IDLE_DAYS","mas":0}},"esperado":true}]},"hash":"e7f98c38e4ac187ad95e08f25004398750832d6215ad718018c0b5bf3c106af3","hash_paquete":"acab96713c19d770ac7a95822baa8cfa2aa7e72b857e414a1a84f3282e60d851","hash_evaluado":"e7f98c38e4","hash_paquete_10":"acab96713c"}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb;
BEGIN
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 n:=n+1;
 END LOOP;
 IF n<>2 OR vectors<>19 THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 -- Independent judgment and AUTO promotion must precede all new coverage; no fabricated judgment.
 RAISE NOTICE 'S22_PROPOSALS_PASS 2 candidates 19 vectors; independent judgment pending';
END $s22$;
COMMIT;
